type Profile = { id: string; full_name: string; email: string; role: string; department: string | null; college: string | null; is_active: boolean };
type Assignment = { id:string; evaluator_id:string; instructor_id:string; form_type:FormType; course_title:string; course_code:string; academic_year:string; semester:number; batch:number|null; due_date:string|null; status:"open"|"submitted"|"closed"; created_at:string; submitted_at:string|null; instructor?:{full_name:string;department:string|null;college:string|null}; evaluator?:{full_name:string;role:string} };
type Notice = { type:"success"|"error"|"info"; text:string } | null;
type Page = "overview"|"evaluations"|"results"|"accounts"|"assignments"|"fill";
const FORMS:FormType[]=["student","department_head","peer","self"];
const RATINGS:Rating[]=[5,4,3,2,1,0,"NA"];
const cx=(...values:Array<string|false|null|undefined>)=>values.filter(Boolean).join(" ");
const initials=(name="")=>name.trim().split(/\s+/).filter(Boolean).slice(0,2).map((x)=>x[0]).join("").toUpperCase()||"AU";
const dateText=(date?:string|null)=>date?new Date(date+"T00:00:00").toLocaleDateString(undefined,{month:"short",day:"numeric",year:"numeric"}):"No deadline";
const formCode=(type:FormType)=>({student:"FORM A",department_head:"FORM B",peer:"FORM C",self:"FORM D"}[type]);

function BrandMark(){return <div className="brand-mark" aria-label="AUPES mark"><span>A</span><i/><b>U</b></div>}
function Brand({light=false}:{light?:boolean}){return <div className={cx("brand",light&&"brand-light")}><BrandMark/><div><strong>AUPES</strong><span>AMBO UNIVERSITY</span></div></div>}
function Button({children,onClick,type="button",variant="primary",disabled,className=""}:{children:React.ReactNode;onClick?:()=>void;type?:"button"|"submit";variant?:"primary"|"outline"|"ghost";disabled?:boolean;className?:string}){return <button type={type} disabled={disabled} onClick={onClick} className={cx("btn","btn-"+variant,className)}>{children}</button>}
function Avatar({name}:{name:string}){return <span className="avatar">{initials(name)}</span>}
function Notice({notice,onClose}:{notice:Notice;onClose?:()=>void}){if(!notice)return null;return <div className={cx("notice","notice-"+notice.type)}>{notice.type==="success"?<CheckCircle2 size={17}/>:notice.type==="error"?<CircleHelp size={17}/>:<ShieldCheck size={17}/>}<span>{notice.text}</span>{onClose&&<button onClick={onClose} className="notice-close" aria-label="Dismiss"><X size={15}/></button>}</div>}
function Loading({label="Loading your workspace…"}:{label?:string}){return <div className="loading-screen"><BrandMark/><LoaderCircle size={21} className="spin"/><span>{label}</span></div>}

function PublicLink({to,navigate,children,className="",onAfterNavigate}:{to:string;navigate:(to:string)=>void;children:React.ReactNode;className?:string;onAfterNavigate?:()=>void}){
 return <a href={to} className={className} onClick={e=>{if(e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigate(to);onAfterNavigate?.();}}>{children}</a>;
}
